package vn.svframe.svframelib.api.crafting.ingredients; import java.util.*; public class MythicBlueprintInventory { private final MythicRecipeInventory main,result; private final Map<String,MythicRecipeInventory> side=new LinkedHashMap<>(); public MythicBlueprintInventory(MythicRecipeInventory main,MythicRecipeInventory result){this.main=main;this.result=result;} public MythicRecipeInventory getMainInventory(){return main;} public MythicRecipeInventory getResultInventory(){return result;} public MythicRecipeInventory getSideInventory(String n){return side.get(n);} public boolean hasSideInventories(String n){return side.containsKey(n);} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>(side.keySet());} public void addSideInventory(String n,MythicRecipeInventory i){side.put(n,i);} public void clearSideInventories(){side.clear();} public MythicBlueprintInventory cloneInventory(){MythicBlueprintInventory b=new MythicBlueprintInventory(main.clone(),result.clone());side.forEach((k,v)->b.addSideInventory(k,v.clone()));return b;} }
